window.HOEREN_TESTS[96] = {"id":"in-der-aenderungsschneiderei","name":"In der Änderungsschneiderei","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist die Schneiderei Nadel und Faden. Ihre Hose ist fertig — aber wir mussten sie nicht nur kürzen, sondern auch enger machen. Deshalb kostet es etwas mehr als besprochen, insgesamt 20 Euro. Sie können sie ab morgen abholen. Bringen Sie bitte den Abholschein mit. Danke!","gender":"f","q":"Was wurde an der Hose gemacht?","opts":["Gekürzt und enger gemacht.","Nur gekürzt.","Nur enger gemacht."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Pass auf, ich habe für die Hochzeit einen Anzug gekauft, aber die Ärmel sind zu lang. Ich bringe ihn zur Änderungsschneiderei. Hoffentlich schaffen die das bis Samstag. Du kennst dich aus, geht so etwas schnell? Ruf zurück, die Hochzeit ist schon übermorgen, ich bin nervös!","gender":"m","q":"Was ist mit Markus' Anzug?","opts":["Die Ärmel sind zu lang.","Er ist zu klein.","Er hat einen Fleck."],"correct":0},{"transcript":"Achtung Kunden: Bitte beachten Sie unsere Preise. Eine Hose kürzen kostet 12 Euro, einen Reißverschluss wechseln 15 Euro. Ein Knopf annähen ist günstig, nur 3 Euro, nicht 12 und nicht 15. Für größere Änderungen machen wir vorher ein Angebot. Express gegen Aufpreis. Fragen Sie einfach, wir beraten Sie gern! Bis bald!","gender":"m","q":"Was kostet das Annähen eines Knopfes?","opts":["15 Euro.","12 Euro.","3 Euro."],"correct":2},{"transcript":"Hi Lisa, hier ist Anna. Ich habe abgenommen und meine ganzen Kleider sind zu groß! Statt alles wegzuwerfen, bringe ich sie zur Schneiderei und lasse sie enger machen. Das ist billiger als neue zu kaufen und besser für die Umwelt. Du hast doch auch ein paar Lieblingsstücke. Bis bald!","gender":"f","q":"Warum bringt Anna die Kleider zur Schneiderei?","opts":["Sie sind kaputt.","Sie sind zu groß geworden.","Sie sind zu alt."],"correct":1},{"transcript":"Liebe Kunden: Werfen Sie kaputte Kleidung nicht weg. Oft können wir sie reparieren — ein Loch stopfen, eine Naht nähen, einen Reißverschluss erneuern. Das spart Geld und schont die Umwelt. Reparieren statt wegwerfen ist wieder modern, besser als neue Kleidung zu kaufen. Bringen Sie Ihre Lieblingsstücke zu uns. Wir helfen gern! Danke!","gender":"f","q":"Wozu rät die Schneiderei?","opts":["Kaputte Kleidung wegzuwerfen.","Neue Kleidung zu kaufen.","Reparieren statt wegwerfen."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer braucht welche Änderung? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Schneider hat heute noch Zeit. Was sollen wir ändern lassen?"},{"speaker":"Lisa","gender":"f","text":"Ich habe die Sachen auf dem Arm. Fünf Teile und jedes hat ein anderes Problem."},{"speaker":"Lukas","gender":"m","text":"Ich lasse die Hose kürzen. Unten ist sie viel zu lang für meine Schuhe."},{"speaker":"Lisa","gender":"f","text":"Das macht er bis morgen. Lässt jemand die Ärmel kürzen?"},{"speaker":"Lukas","gender":"m","text":"Ärmel kürzen wir nicht. Bei allen passt es oben."},{"speaker":"Lisa","gender":"f","text":"Ich lasse das Kleid enger machen."},{"speaker":"Lukas","gender":"m","text":"Für die Feier am Samstag passt das. Tom hat eine Jacke und sie geht nicht zu."},{"speaker":"Lisa","gender":"f","text":"Tom lässt den Reißverschluss wechseln. An der Jacke ist er kaputt."},{"speaker":"Lukas","gender":"m","text":"Soll jemand eine Naht nähen? An einer Stelle ist etwas offen."},{"speaker":"Lisa","gender":"f","text":"Eine Naht nähen wir auch nicht."},{"speaker":"Lukas","gender":"m","text":"Sara hat nach der Feier ein Problem an der Jacke."},{"speaker":"Lisa","gender":"f","text":"Sara lässt ein Loch stopfen. Es ist klein und man sieht es noch."},{"speaker":"Lukas","gender":"m","text":"Das geht schnell. Tim hat am Mantel zwei lose Teile."},{"speaker":"Lisa","gender":"f","text":"Tim lässt Knöpfe annähen. Vor dem Winter soll der Mantel wieder zugehen."},{"speaker":"Lukas","gender":"m","text":"Die sind klein und rund."},{"speaker":"Lisa","gender":"f","text":"Ich lege die Sachen auf den Tisch."}],"options":[{"letter":"a","text":"Ärmel kürzen"},{"letter":"b","text":"Naht nähen"},{"letter":"c","text":"Reißverschluss wechseln"},{"letter":"d","text":"Rock weiter machen"},{"letter":"e","text":"Hose kürzen"},{"letter":"f","text":"Knöpfe annähen"},{"letter":"g","text":"Kleid enger machen"},{"letter":"h","text":"Loch stopfen"},{"letter":"i","text":"Futter erneuern"}],"items":[{"person":"Lukas","correct":"e"},{"person":"Lisa","correct":"g"},{"person":"Tom","correct":"c"},{"person":"Sara","correct":"h"},{"person":"Tim","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Wann ist die Hose fertig? Morgen, in drei Tagen oder in einer Woche?"},{"speaker":"Schneider","gender":"m","text":"Normal in drei Tagen. Eine Woche brauchen wir selten, morgen nur mit Express."},{"speaker":"Kundin","gender":"f","text":"Geht es schneller? Morgen statt in drei Tagen?"},{"speaker":"Schneider","gender":"m","text":"Mit Express bis morgen, plus 5 Euro. Normal in drei Tagen, nicht in einer Woche."},{"speaker":"Kundin","gender":"f","text":"Dann normal in drei Tagen. Danke."}],"q":"Wann ist die Hose normal fertig?","opts":["In drei Tagen.","Morgen.","In einer Woche."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Können Sie die Ärmel kürzen? Einen Zentimeter, drei oder fünf?"},{"speaker":"Schneiderin","gender":"f","text":"Ja, ich messe gleich nach. Einen Zentimeter ist wenig, fünf oft zu viel."},{"speaker":"Mann","gender":"m","text":"Wie viel kürzer? Drei Zentimeter, oder fünf?"},{"speaker":"Schneiderin","gender":"f","text":"Etwa drei Zentimeter. Nicht einen und nicht fünf, drei Zentimeter passen gut."},{"speaker":"Mann","gender":"m","text":"Gut, dann drei Zentimeter. Danke."}],"q":"Um wie viel werden die Ärmel gekürzt?","opts":["Drei Zentimeter.","Einen Zentimeter.","Fünf Zentimeter."],"correct":0},{"lines":[{"speaker":"Frau","gender":"f","text":"Der Reißverschluss klemmt. Reparieren Sie ihn, tauschen Sie ihn aus, oder lassen Sie ihn so?"},{"speaker":"Schneider","gender":"m","text":"Den muss ich austauschen. Reparieren hält nicht lange, und so lassen geht nicht."},{"speaker":"Frau","gender":"f","text":"Lohnt sich das noch? Also austauschen, nicht reparieren?"},{"speaker":"Schneider","gender":"m","text":"Ja, die Jacke ist sonst noch top. Ich tausche ihn aus, repariere ihn nicht und lasse ihn nicht so."},{"speaker":"Frau","gender":"f","text":"Dann bitte austauschen. Danke."}],"q":"Was macht der Schneider mit dem Reißverschluss?","opts":["Er repariert ihn.","Er tauscht ihn aus.","Er lässt ihn so."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Was kostet das Kürzen? 12 Euro, 20 oder 24?"},{"speaker":"Schneiderin","gender":"f","text":"Bei einer Jeans 12 Euro. 24 Euro wären zwei zum normalen Preis, ohne Rabatt."},{"speaker":"Kunde","gender":"m","text":"Und bei zwei Hosen? 20 oder 24?"},{"speaker":"Schneiderin","gender":"f","text":"Dann mache ich Ihnen 20 Euro. Nicht 12 für zwei und nicht 24, zwei Hosen zusammen 20. Einverstanden?"},{"speaker":"Kunde","gender":"m","text":"Super, dann zwei Hosen für 20 Euro. Danke schön!"}],"q":"Was kosten zwei Hosen zusammen?","opts":["12 Euro.","24 Euro.","20 Euro."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Muss ich zur Anprobe kommen? Oder nichts tun, oder später wiederkommen?"},{"speaker":"Schneider","gender":"m","text":"Ja, einmal vor der Änderung. Nichts tun geht nicht, und später wiederkommen brauchen Sie nur zur Abholung."},{"speaker":"Kundin","gender":"f","text":"Geht das jetzt gleich? Also zur Anprobe, und nicht ohne Anprobe?"},{"speaker":"Schneider","gender":"m","text":"Ja, kommen Sie in die Kabine. Zur Anprobe jetzt, nicht ohne Anprobe und nicht erst später."},{"speaker":"Kundin","gender":"f","text":"Gut, dann jetzt zur Anprobe. Danke."}],"q":"Was muss die Kundin machen?","opts":["Später wiederkommen.","Nichts.","Zur Anprobe kommen."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Yilmaz, einer Schneiderin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Yilmaz, wie hat sich Ihre Arbeit in den letzten Jahren verändert?"},{"speaker":"Yilmaz","gender":"f","text":"Früher kauften die Leute oft neu. Jetzt lassen sie Kleidung wieder reparieren. Heute lassen die Leute Kleidung wieder mehr reparieren, das merke ich klar."},{"speaker":"Reporter","gender":"m","text":"Was sind die häufigsten Aufträge in der Werkstatt?"},{"speaker":"Yilmaz","gender":"f","text":"Hosen kürzen, das mache ich jeden Tag. Auch Reißverschlüsse wechseln. Hosen kürzen ist ein häufiger Auftrag, fast stündlich."},{"speaker":"Reporter","gender":"m","text":"Lohnt sich das Reparieren immer, auch bei billiger Kleidung?"},{"speaker":"Yilmaz","gender":"f","text":"Nicht immer. Bei billiger Kleidung ist es manchmal zu teuer. Bei guter lohnt es sich. Das Reparieren lohnt sich also nicht immer, das muss man prüfen."},{"speaker":"Reporter","gender":"m","text":"Können junge Leute noch nähen, oder immer weniger?"},{"speaker":"Yilmaz","gender":"f","text":"Leider immer weniger. Manche kommen nur, um einen Knopf annähen zu lassen. Immer weniger junge Leute können nähen, das ist schade."},{"speaker":"Reporter","gender":"m","text":"Was wünschen Sie sich? Ist Reparieren gut für die Umwelt? Lohnt sich das?"},{"speaker":"Yilmaz","gender":"f","text":"Dass die Menschen Kleidung wieder mehr schätzen. Reparieren ist gut für die Umwelt, nicht schlecht. Weniger wegwerfen hilft uns allen. Kommen Sie vorbei!"}],"items":[{"q":"Heute lassen die Leute Kleidung wieder mehr reparieren.","correct":"ja"},{"q":"Hosen kürzen ist ein häufiger Auftrag.","correct":"ja"},{"q":"Frau Yilmaz sagt, das Reparieren lohnt sich immer.","correct":"nein"},{"q":"Immer weniger junge Leute können nähen.","correct":"ja"},{"q":"Sie findet Reparieren schlecht für die Umwelt.","correct":"nein"}]}]};
